ALTER TRIGGER "GRUPO5"."INSERTAR_FLUJOCAJA_CABECERA" ENABLE;
--------------------------------------------------------
--  DDL for Procedure EJEMPLO
--------------------------------------------------------
set define off;

  CREATE OR REPLACE NONEDITIONABLE PROCEDURE "GRUPO5"."EJEMPLO" 
    (COD_CIA IN PFLUJOCAJA.CODCIA%TYPE, 
    COD_PYTO IN PFLUJOCAJA.CODPYTO%TYPE, 
    ING_EGR IN PFLUJOCAJA.INGEGR%TYPE, 
    COD_PARTIDA IN PFLUJOCAJA.CODPARTIDA%TYPE,
    COSTO_TOTAL IN COMP_PAGOCAB.IMPTOTALMN%TYPE,
    FECHA IN VTACOMP_PAGOCAB.FECCP%TYPE,
    PROYECTADO_REAL IN CLIENTE.VIGENTE%TYPE)
IS
    nroDeMes NUMBER(2) := TO_CHAR(FECHA, 'MM');
    nroDeAnio NUMBER(4) := TO_CHAR(FECHA, 'YYYY');
    valorAuxiliarActual NUMBER(10);
    valorAuxiliarPadre NUMBER(10);
    codHijo NUMBER(10);
    contador NUMBER(20);

    PROCEDURE UpdateMes(
        campo IN VARCHAR2,
        valor IN OUT NUMBER
    ) IS
    BEGIN
        EXECUTE IMMEDIATE 'SELECT ' || campo || ' INTO :valor FROM PFLUJOCAJA_DET WHERE CODCIA = :COD_CIA AND CODPYTO = :COD_PYTO AND INGEGR = :ING_EGR AND CODPARTIDA = :COD_PARTIDA AND ANNO = :nroDeAnio'
            USING OUT valor, COD_CIA, COD_PYTO, ING_EGR, COD_PARTIDA, nroDeAnio;
        EXECUTE IMMEDIATE 'UPDATE PFLUJOCAJA_DET SET ' || campo || ' = :1 + :2 WHERE CODCIA = :COD_CIA AND CODPYTO = :COD_PYTO AND INGEGR = :ING_EGR AND CODPARTIDA = :COD_PARTIDA AND ANNO = :nroDeAnio'
            USING valor, COSTO_TOTAL, COD_CIA, COD_PYTO, ING_EGR, COD_PARTIDA, nroDeAnio;

        codHijo := COD_PARTIDA;
        WHILE getPPadre(codHijo, ING_EGR, COD_PYTO) <> 0 LOOP
            EXECUTE IMMEDIATE 'SELECT ' || campo || ' INTO :valor FROM PFLUJOCAJA_DET WHERE CODCIA = :COD_CIA AND CODPYTO = :COD_PYTO AND INGEGR = :ING_EGR AND CODPARTIDA = :COD_PADRE AND ANNO = :nroDeAnio'
                USING OUT valorAuxiliarPadre, COD_CIA, COD_PYTO, ING_EGR, getPPadre(codHijo, ING_EGR, COD_PYTO), nroDeAnio;
            EXECUTE IMMEDIATE 'UPDATE PFLUJOCAJA_DET SET ' || campo || ' = :1 + :2 WHERE CODCIA = :COD_CIA AND CODPYTO = :COD_PYTO AND INGEGR = :ING_EGR AND CODPARTIDA = :COD_PADRE AND ANNO = :nroDeAnio'
                USING valorAuxiliarPadre, COSTO_TOTAL, COD_CIA, COD_PYTO, ING_EGR, getPPadre(codHijo, ING_EGR, COD_PYTO), nroDeAnio;
            codHijo := getPPadre(codHijo, ING_EGR, COD_PYTO);
        END LOOP;
    END UpdateMes;
BEGIN
    IF PROYECTADO_REAL = 'P' THEN
        CASE nroDeMes
            WHEN 1 THEN UpdateMes('IMPENE', valorAuxiliarActual);
            WHEN 2 THEN UpdateMes('IMPFEB', valorAuxiliarActual);
            WHEN 3 THEN UpdateMes('IMPMAR', valorAuxiliarActual);
            WHEN 4 THEN UpdateMes('IMPABR', valorAuxiliarActual);
            WHEN 5 THEN UpdateMes('IMPMAY', valorAuxiliarActual);
            WHEN 6 THEN UpdateMes('IMPJUN', valorAuxiliarActual);
            WHEN 7 THEN UpdateMes('IMPJUL', valorAuxiliarActual);
            WHEN 8 THEN UpdateMes('IMPAGO', valorAuxiliarActual);
            WHEN 9 THEN UpdateMes('IMPSEP', valorAuxiliarActual);
            WHEN 10 THEN UpdateMes('IMPOCT', valorAuxiliarActual);
            WHEN 11 THEN UpdateMes('IMPNOV', valorAuxiliarActual);
            WHEN 12 THEN UpdateMes('IMPDIC', valorAuxiliarActual);
        END CASE;
    ELSIF PROYECTADO_REAL = 'R' THEN
        CASE nroDeMes
            WHEN 1 THEN UpdateMes('IMPREALENE', valorAuxiliarActual);
            WHEN 2 THEN UpdateMes('IMPREALFEB', valorAuxiliarActual);
            WHEN 3 THEN UpdateMes('IMPREALMAR', valorAuxiliarActual);
            WHEN 4 THEN UpdateMes('IMPREALABR', valorAuxiliarActual);
            WHEN 5 THEN UpdateMes('IMPREALMAY', valorAuxiliarActual);
            WHEN 6 THEN UpdateMes('IMPREALJUN', valorAuxiliarActual);
            WHEN 7 THEN UpdateMes('IMPREALJUL', valorAuxiliarActual);
            WHEN 8 THEN UpdateMes('IMPREALAGO', valorAuxiliarActual);
            WHEN 9 THEN UpdateMes('IMPREALSEP', valorAuxiliarActual);
            WHEN 10 THEN UpdateMes('IMPREALOCT', valorAuxiliarActual);
            WHEN 11 THEN UpdateMes('IMPREALNOV', valorAuxiliarActual);
            WHEN 12 THEN UpdateMes('IMPREALDIC', valorAuxiliarActual);
        END CASE;
    END IF;

    contador := duracionProyecto(COD_PYTO);
    WHILE contador > 0 LOOP
        contador := contador - 1;
        UPDATE PFLUJOCAJA_DET F1
        SET F1.IMPINI = NVL((SELECT F2.IMPACUM FROM PFLUJOCAJA_DET F2 WHERE F2.ANNO = (F1.ANNO - 1) AND F2.CODPARTIDA = F1.CODPARTIDA AND F2.INGEGR = F1.INGEGR AND F2.CODPYTO = F1.CODPYTO AND F2.CODCIA = F1.CODCIA), 0),
            F1.IMPREALINI = NVL((SELECT F2.IMPREALACUM FROM PFLUJOCAJA_DET F2 WHERE F2.ANNO = (F1.ANNO - 1) AND F2.CODPARTIDA = F1.CODPARTIDA AND F2.INGEGR = F1.INGEGR AND F2.CODPYTO = F1.CODPYTO AND F2.CODCIA = F1.CODCIA), 0),
            IMPACUM = IMPINI + IMPENE + IMPFEB + IMPMAR + IMPABR + IMPMAY + IMPJUN + IMPJUL + IMPAGO + IMPSEP + IMPOCT + IMPNOV + IMPDIC,
            IMPREALACUM = IMPREALINI + IMPREALENE + IMPREALFEB + IMPREALMAR + IMPREALABR + IMPREALMAY + IMPREALJUN + IMPREALJUL + IMPREALAGO + IMPREALSEP + IMPREALOCT + IMPREALNOV + IMPREALDIC;
    END LOOP;
END EJEMPLO;

