--------------------------------------------------------
--  DDL for Procedure INSERTAR_PDPROY_PARTIDA_MEZCLA
--------------------------------------------------------
set define off;

  CREATE OR REPLACE NONEDITIONABLE PROCEDURE "GRUPO5"."INSERTAR_PDPROY_PARTIDA_MEZCLA" (
    CODCIA IN PDPROY_PARTIDA_MEZCLA.CODCIA%TYPE,
    CODPYTO IN PDPROY_PARTIDA_MEZCLA.CODPYTO%TYPE,
    INGEGR IN PDPROY_PARTIDA_MEZCLA.INGEGR%TYPE,
    NROVERSION IN PDPROY_PARTIDA_MEZCLA.NROVERSION%TYPE,
    CODPART IN PDPROY_PARTIDA_MEZCLA.CODPARTIDA%TYPE,
    CORR IN PDPROY_PARTIDA_MEZCLA.CORR%TYPE,
    EDESEMB IN PDPROY_PARTIDA_MEZCLA.EDESEMBOLSO%TYPE,
