    FECDESEMB IN PDPROY_PARTIDA_MEZCLA.FECDESEMBOLSO%TYPE,
    IMPDESEMNETO IN PDPROY_PARTIDA_MEZCLA.IMPDESEMBNETO%TYPE,
    IMPDESEMIGV IN PDPROY_PARTIDA_MEZCLA.IMPDESEMBIGV%TYPE,
    IMPDESEMTOT IN PDPROY_PARTIDA_MEZCLA.IMPDESEMBTOT%TYPE,
    SEMI IN PDPROY_PARTIDA_MEZCLA.SEMILLA%TYPE,
    REPETICION IN PDPROY_PARTIDA_MEZCLA.CODCIA%TYPE)
IS
BEGIN

IF(INGEGR = 'E') THEN
 IF(REPETICION = 0) THEN
  IF(EDESEMB = 1) THEN
  INSERT INTO PDPROY_PARTIDA_MEZCLA VALUES
  (CODCIA,CODPYTO,INGEGR,NROVERSION,CODPART,CORR, 
  SEC_PDPROY_PARTIDA_MEZCLA_E.NEXTVAL,3,EDESEMB,SEC_DPROY_PARTIDA_MEZCLA_ADELANTO.NEXTVAL,4,
  ECPAGO,FECDESEMB,IMPDESEMNETO,IMPDESEMIGV,IMPDESEMTOT,SEC_PDPROY_PARTIDA_MEZCLA_SEMILLA_E.NEXTVAL);
  ELSE 
  INSERT INTO PDPROY_PARTIDA_MEZCLA VALUES
  (CODCIA,CODPYTO,INGEGR,NROVERSION,CODPART,CORR, 
  SEC_PDPROY_PARTIDA_MEZCLA_E.NEXTVAL,3,EDESEMB,SEC_PDPROY_PARTIDA_MEZCLA_PAGO.NEXTVAL,4,
  ECPAGO,FECDESEMB,IMPDESEMNETO,IMPDESEMIGV,IMPDESEMTOT,SEC_PDPROY_PARTIDA_MEZCLA_SEMILLA_E.NEXTVAL);
  END IF;
   ELSE
   IF(EDESEMB = 1) THEN
   INSERT INTO PDPROY_PARTIDA_MEZCLA VALUES
   (CODCIA,CODPYTO,INGEGR,NROVERSION,CODPART,CORR, 
   SEC_PDPROY_PARTIDA_MEZCLA_E.NEXTVAL,3,EDESEMB,SEC_PDPROY_PARTIDA_MEZCLA_ADELANTO.NEXTVAL,4,
   ECPAGO,FECDESEMB,IMPDESEMNETO,IMPDESEMIGV,IMPDESEMTOT,SEMI);
   ELSE
   INSERT INTO PDPROY_PARTIDA_MEZCLA VALUES
   (CODCIA,CODPYTO,INGEGR,NROVERSION,CODPART,CORR, 
   SEC_PDPROY_PARTIDA_MEZCLA_E.NEXTVAL,3,EDESEMB,SEC_PDPROY_PARTIDA_MEZCLA_PAGO.NEXTVAL,4,
   ECPAGO,FECDESEMB,IMPDESEMNETO,IMPDESEMIGV,IMPDESEMTOT,SEMI);
   END IF;
 END IF;
END IF;

IF(INGEGR = 'I') THEN
 IF(REPETICION = 0) THEN
  IF(EDESEMB = 1) THEN
  INSERT INTO PDPROY_PARTIDA_MEZCLA VALUES
  (CODCIA,CODPYTO,INGEGR,NROVERSION,CODPART,CORR, 
  SEC_PDPROY_PARTIDA_MEZCLA_I.NEXTVAL,3,EDESEMB,SEC_PDPROY_PARTIDA_MEZCLA_ADELANTO.NEXTVAL,4,
  ECPAGO,FECDESEMB,IMPDESEMNETO,IMPDESEMIGV,IMPDESEMTOT,SEC_PDPROY_PARTIDA_MEZCLA_SEMILLA_I.NEXTVAL);
  ELSE 
  INSERT INTO PDPROY_PARTIDA_MEZCLA VALUES
  (CODCIA,CODPYTO,INGEGR,NROVERSION,CODPART,CORR, 
  SEC_PDPROY_PARTIDA_MEZCLA_I.NEXTVAL,3,EDESEMB,SEC_PDPROY_PARTIDA_MEZCLA_PAGO.NEXTVAL,4,
  ECPAGO,FECDESEMB,IMPDESEMNETO,IMPDESEMIGV,IMPDESEMTOT,SEC_PDPROY_PARTIDA_MEZCLA_SEMILLA_I.NEXTVAL);
  END IF;
   ELSE
   IF(EDESEMB = 1) THEN
   INSERT INTO PDPROY_PARTIDA_MEZCLA VALUES
   (CODCIA,CODPYTO,INGEGR,NROVERSION,CODPART,CORR, 
   SEC_PDPROY_PARTIDA_MEZCLA_I.NEXTVAL,3,EDESEMB,SEC_PDPROY_PARTIDA_MEZCLA_ADELANTO.NEXTVAL,4,
   ECPAGO,FECDESEMB,IMPDESEMNETO,IMPDESEMIGV,IMPDESEMTOT,SEMI);
   ELSE
   INSERT INTO PDPROY_PARTIDA_MEZCLA VALUES
   (CODCIA,CODPYTO,INGEGR,NROVERSION,CODPART,CORR, 
   SEC_PDPROY_PARTIDA_MEZCLA_I.NEXTVAL,3,EDESEMB,SEC_PDPROY_PARTIDA_MEZCLA_PAGO.NEXTVAL,4,
   ECPAGO,FECDESEMB,IMPDESEMNETO,IMPDESEMIGV,IMPDESEMTOT,SEMI);
   END IF;
 END IF;
END IF;

UPDATE_PFLUJOCAJA_DET_UNALINEA_Y_GLOBAL(CODCIA,CODPYTO,INGEGR,CODPART,IMPDESEMTOT,FECDESEMB,'P');

END;

