/
--------------------------------------------------------
--  DDL for Procedure INSERTAR_PPROY_PARTIDA
--------------------------------------------------------
set define off;

  CREATE OR REPLACE NONEDITIONABLE PROCEDURE "GRUPO5"."INSERTAR_PPROY_PARTIDA" (
    CODPYTO IN PPROY_PARTIDA.CODPYTO%TYPE,
    NROVERSION IN PPROY_PARTIDA.NROVERSION%TYPE,
    CODCIA IN PPROY_PARTIDA.CODCIA%TYPE,
    INGEGRE IN PPROY_PARTIDA.INGEGR%TYPE,
    CODP IN PPROY_PARTIDA.CODPARTIDA%TYPE,
    CODPAR IN PPROY_PARTIDA.CODPARTIDAS%TYPE,
    TABE IN PPROY_PARTIDA.TABESTADO%TYPE,
    CODE IN PPROY_PARTIDA.CODESTADO%TYPE,
    VIG IN PPROY_PARTIDA.VIGENTE%TYPE)
IS
BEGIN
    BEGIN
        INSERT INTO PPROY_PARTIDA (CODCIA, CODPYTO, NROVERSION, INGEGR, CODPARTIDA, CODPARTIDAS, FLGCC, NIVEL, UNIMED, TABESTADO, CODESTADO, VIGENTE)
        VALUES (CODCIA, CODPYTO, NROVERSION, INGEGRE, CODP, CODPAR, '1', 1, '1', TABE, CODE, VIG);
    EXCEPTION
        WHEN DUP_VAL_ON_INDEX THEN
             UPDATE PPROY_PARTIDA
            SET CODPARTIDAS = CODPAR,
                FLGCC = '1',
                NIVEL = 1,
                UNIMED = '1',
                TABESTADO = TABE,
                CODESTADO = CODE,
                VIGENTE = VIG
            WHERE CODCIA = CODCIA AND
                  CODPYTO = CODPYTO AND
                  NROVERSION = NROVERSION AND
                  INGEGR = INGEGRE AND
                  CODPARTIDA = CODP;
            NULL;
    END;
END;

/
--------------------------------------------------------
--  DDL for Procedure INSERTAR_PPROY_PARTIDA_MEZCLA
--------------------------------------------------------
set define off;

  CREATE OR REPLACE NONEDITIONABLE PROCEDURE "GRUPO5"."INSERTAR_PPROY_PARTIDA_MEZCLA" (
    CODC IN PPROY_PARTIDA_MEZCLA.CODCIA%TYPE,
    CODPYTO IN PPROY_PARTIDA_MEZCLA.CODPYTO%TYPE,
    NROVERSION IN PPROY_PARTIDA_MEZCLA.NROVERSION%TYPE,
    PADCOD IN PPROY_PARTIDA_MEZCLA.PADCODPARTIDA%TYPE,
    INEG IN PPROY_PARTIDA_MEZCLA.IngEgr%TYPE,
    CAN IN PPROY_PARTIDA_MEZCLA.CANT%TYPE)
AS
CURSOR cpm IS
SELECT CODPARTIDA,PADCODPARTIDA,TUNIMED,EUNIMED,COSTOUNIT,NIVEL,ORDEN 
FROM PPARTIDA_MEZCLA WHERE CODCIA=CODC AND PADCODPARTIDA=PADCOD AND INGEGR=INEG;
CURSOR cpm2 IS
SELECT CODPARTIDA,PADCODPARTIDA,TUNIMED,EUNIMED,COSTOUNIT,NIVEL,ORDEN 
FROM PPARTIDA_MEZCLA WHERE CODCIA=CODC AND CODPARTIDA=PADCOD AND PADCODPARTIDA=0 AND INGEGR=INEG;
V_total PPROY_PARTIDA_MEZCLA.COSTOTOT%TYPE;
BEGIN
IF(INEG = 'E') THEN
 FOR R1 IN CPM2 LOOP
 V_total := CAN*R1.COSTOUNIT;
 INSERT INTO PPROY_PARTIDA_MEZCLA VALUES(CODC,CODPYTO,INEG,NROVERSION,R1.CODPARTIDA,
 SEC_PPROY_PARTIDA_MEZCLA_E.nextval,R1.PADCODPARTIDA,R1.TUNIMED,R1.EUNIMED,
 R1.NIVEL,R1.ORDEN,R1.COSTOUNIT,CAN,V_total);
 END LOOP;

 FOR R2 IN CPM LOOP
 V_total := CAN*R2.COSTOUNIT;
 INSERT INTO PPROY_PARTIDA_MEZCLA VALUES(CODC,CODPYTO,INEG,NROVERSION,R2.CODPARTIDA,
 SEC_PPROY_PARTIDA_MEZCLA_E.nextval,R2.PADCODPARTIDA,R2.TUNIMED,R2.EUNIMED,
 R2.NIVEL,R2.ORDEN,R2.COSTOUNIT,CAN,V_total);
 END LOOP;
END IF;
IF(INEG = 'I') THEN
 FOR R3 IN CPM2 LOOP
 V_total := CAN*R3.COSTOUNIT;
 INSERT INTO PPROY_PARTIDA_MEZCLA VALUES(CODC,CODPYTO,INEG,NROVERSION,R3.CODPARTIDA,
 SEC_PPROY_PARTIDA_MEZCLA_I.nextval,R3.PADCODPARTIDA,R3.TUNIMED,R3.EUNIMED,
 R3.NIVEL,R3.ORDEN,R3.COSTOUNIT,CAN,V_total);
 END LOOP;

 FOR R4 IN CPM LOOP
 V_total := CAN*R4.COSTOUNIT;
 INSERT INTO PPROY_PARTIDA_MEZCLA VALUES(CODC,CODPYTO,INEG,NROVERSION,R4.CODPARTIDA,
 SEC_PPROY_PARTIDA_MEZCLA_I.nextval,R4.PADCODPARTIDA,R4.TUNIMED,R4.EUNIMED,
 R4.NIVEL,R4.ORDEN,R4.COSTOUNIT,CAN,V_total);
 END LOOP;
END IF;
END;

