    contador:=duracionProyecto(COD_PYTO);
    WHILE (contador>0)
            LOOP
                contador:=contador-1;
                UPDATE PFLUJOCAJA_DET F1 SET F1.IMPINI = 
                NVL((SELECT F2.IMPACUM FROM PFLUJOCAJA_DET F2 WHERE F2.ANNO=(F1.ANNO-1) AND F2.CODPARTIDA=F1.CODPARTIDA AND F2.INGEGR=F1.INGEGR AND F2.CODPYTO=F1.CODPYTO AND F2.CODCIA=F1.CODCIA),0); 

                UPDATE PFLUJOCAJA_DET F1 SET F1.IMPREALINI = 
                NVL((SELECT F2.IMPREALACUM FROM PFLUJOCAJA_DET F2 WHERE F2.ANNO=(F1.ANNO-1) AND F2.CODPARTIDA=F1.CODPARTIDA AND F2.INGEGR=F1.INGEGR AND F2.CODPYTO=F1.CODPYTO AND F2.CODCIA=F1.CODCIA),0); 

                UPDATE PFLUJOCAJA_DET SET IMPACUM = IMPINI+IMPENE+IMPFEB+IMPMAR+IMPABR+IMPMAY+IMPJUN+IMPJUL+IMPAGO+IMPSEP+IMPOCT+IMPNOV+IMPDIC;
                UPDATE PFLUJOCAJA_DET SET IMPREALACUM = IMPREALINI+IMPREALENE+IMPREALFEB+IMPREALMAR+IMPREALABR+IMPREALMAY+IMPREALJUN+IMPREALJUL+IMPREALAGO+IMPREALSEP+IMPREALOCT+IMPREALNOV+IMPREALDIC;
    END LOOP;

END UPDATE_PFLUJOCAJA_DET_UNALINEA_Y_GLOBAL;

/
--------------------------------------------------------
--  DDL for Function DURACIONPROYECTO
--------------------------------------------------------

  CREATE OR REPLACE NONEDITIONABLE FUNCTION "GRUPO5"."DURACIONPROYECTO" 
    (COD_PYTO IN PROYECTO.CODPYTO%TYPE)
        return NUMBER
    IS
        duracionEnAnios NUMBER;
    BEGIN
        select count(n) into duracionEnAnios from
        (select distinct rownum n from dual connect by level <= (SELECT ANNOFIN FROM PROYECTO WHERE CODPYTO=COD_PYTO))
        where n >= (SELECT ANNOINI FROM PROYECTO WHERE CODPYTO=COD_PYTO) ORDER BY n;
    RETURN duracionEnAnios;
END duracionProyecto;

/
--------------------------------------------------------
--  DDL for Function GETPADRE
--------------------------------------------------------

  CREATE OR REPLACE NONEDITIONABLE FUNCTION "GRUPO5"."GETPADRE" 
    (NROHIJO IN FLUJOCAJA.CODCIA%TYPE,
     ING_EGR IN FLUJOCAJA.INGEGR%TYPE,
     COD_PYTO IN PROYECTO.CODPYTO%TYPE)
        return NUMBER
    IS
        NROPADRE NUMBER;
    BEGIN
        SELECT PADCODPARTIDA INTO NROPADRE FROM PROY_PARTIDA_MEZCLA WHERE CODPARTIDA = NROHIJO AND INGEGR=ING_EGR AND CODPYTO = COD_PYTO;
    RETURN NROPADRE;
END getPadre;

/
--------------------------------------------------------
--  DDL for Function GETPPADRE
--------------------------------------------------------

  CREATE OR REPLACE NONEDITIONABLE FUNCTION "GRUPO5"."GETPPADRE" 
    (NROHIJO IN PFLUJOCAJA.CODCIA%TYPE,
     ING_EGR IN PFLUJOCAJA.INGEGR%TYPE,
     COD_PYTO IN PROYECTO.CODPYTO%TYPE)
        return NUMBER
    IS
        NROPADRE NUMBER;
    BEGIN
        SELECT PADCODPARTIDA INTO NROPADRE FROM PPROY_PARTIDA_MEZCLA WHERE CODPARTIDA = NROHIJO AND INGEGR=ING_EGR AND CODPYTO = COD_PYTO;
    RETURN NROPADRE;
END getPPadre;

